   "4.3": {
    "caption": "Таблица 4.3 – Описание полей наименования уровней ЦИМ АГР",
    "rows": [
     [
      [
       "Поле",
       1
      ],
      [
       "Значение",
       1
      ],
      [
       "Описание",
       1
      ]
     ],
     [
      [
       "Поле 1",
       1
      ],
      [
       "Номер подобъекта (секции)",
       1
      ],
      [
       "Обязательное поле.\nНомер подобъекта (секции) указывается в формате «Xxx», где «X» – «П» (подобъект) или «С» (секция); «xx» – двузначное обозначение порядкового номера. При отсутствии номера указывается «00», например, П01, С00, С02, С05 и т.п.\nВ случае привязки одного уровня к нескольким подобъектам (секциям) их обозначения указываются диапазоном, например, «С01-С03» – секции 1, 2 и 3.",
       1
      ]
     ],
     [
      [
       "Поле 2",
       1
      ],
      [
       "Номер уровня",
       1
      ],
      [
       "Обязательное поле.\nУказывается номер уровня. Нумерация уровней, относящихся к этажам наземного объекта, должна соответствовать нумерации этажей объекта.\nНумерация надземных этажей начинается с 1 (нижнего надземного этажа объекта).\nДля нумерации цокольного этажа используется номер 0.\nНомера подвальных и подземных уровней обозначаются отрицательными значениями (-1, -2 и т.д.) либо буквенно-цифровыми значениями (П1, П2 и т.д.). Допускается использовать значение 0 при возможности однозначной идентификации расположения уровня ниже уровня 0,000.\nДля нумерации технических пространств с высотой помещений менее 1,8 м, не являющихся этажами, используется обозначение, отражающее между какими этажами оно расположено через знак «-», например, «1-2».\nПримечание: нумерацию уровней, в том числе для подземных объектов, допускается выполнять по иным правилам с обязательной расшифровкой принятой нумерации в приложении к ведомости ЦИМ АГР.",
       1
      ]
     ],
     [
      [
       "Поле 3",
       1
      ],
      [
       "Наименование уровня",
       1
      ],
      [
       "Обязательное поле.\nДля уровней, обозначающих этажи здания, используются следующие наименования:\nЭтаж – надземный этаж, этаж с отметкой пола помещений не ниже планировочной отметки земли.\nПри переменных планировочных отметках земли этаж считается надземным при условии, что более 60% общей площади помещений находится не ниже планировочной отметки уровня земли, либо необходимые по нормам эвакуационные выходы с этажа, имеют непосредственный горизонтальный проход на отметку земли.\nПодземный этаж – этаж с помещениями, расположенными ниже планировочной отметки землина всю высоту помещения.\nПодвальный этаж, подвал – первый подземный этаж с отметкой пола помещений ниже планировочной отметки земли более чем на половину высоты помещений.\nЦокольный этаж – этаж с отметкой пола ниже планировочной отметки земли с наружной стороны стены на высоту не более половины высоты помещений.\nТехнический этаж – этаж для размещения инженерного оборудования и прокладки коммуникаций.\nПримечание: пространство для прокладки коммуникаций высотой менее 1,8 м этажом не является. Такое же пространство высотой до 2,1 м в высотных зданиях не является этажом, но учитывается при подсчёте СПП в ГНС.\nТехническое пространство – пространство для прокладки коммуникаций высотой менее 1,8 м, не являющееся этажом.\nТехническое подполье – технический этаж между перекрытием первого или цокольного этажа и поверхностью грунта для размещения трубопроводов инженерных систем.\nЧердак, технический чердак – пространство между перекрытием верхнего этажа, покрытием здания (крышей) и наружными стенами (при их наличии), расположенное выше перекрытия верхнего этажа.\nМансардный этаж – этаж в чердачном пространстве, фасад которого полностью или частично образован поверхностью (поверхностями) наклонной, ломаной или криволинейной крыши. При этом линия пересечения плоскости крыши и фасада должна располагаться на высоте не более 1,5 м от уровня пола мансардного этажа.\nДля уровней, обозначающих крышу здания, используется следующее наименование:\nКрыша – внешняя несущая и ограждающая конструкция здания или сооружения, предназначенная для защиты помещений от внешних климатических и других воздействий.",
       1
      ]
     ],
     [
      [
       "Поле 4",
       1
      ],
      [
       "Назначение уровня",
       1
      ],
      [
       "Обязательное поле.\nДля уровней, относящихся к этажам здания, указывается значение «основной».\nДля уровней, предназначенных для размещения инженерного оборудования и прокладки коммуникаций, указывается значение «технический».\nДля иных уровней указываются значения «вспомогательный» или «дополнительный».",
       1
      ]
     ],
     [
      [
       "Поле 5",
       1
      ],
      [
       "Отметка",
       1
      ],
      [
       "Обязательное поле.\nУказывается отметка уровня, например: 0,000; -1,700; +3,000.",
       1
      ]
     ]
    ]
   },
